column2:
[Meta]
Version=4

[BulletImpact]
Enabled={0}

[Debug]
; True = também grava as linhas DIAG de cada quadro no BulletImpact.log (acertos, tiros fatais e aleijamentos sempre vão pro log).
LogHits={1}

[Wounds]
; Coluna / pelve / joelho / ossos da perna estilhaçados derrubam a pessoa de vez (ela rasteja), pescoço quebrado
; paralisa, pé estilhaçado deixa mancando. Decidido pelo raio-X de cada acerto.
Crippling={2}
; O dano da sua arma contra todo mundo, 1.0 = original. Menor = as pessoas aguentam mais tiros antes de morrer.
PlayerDamage={3}
; Um tiro cujo raio-X destrói o cérebro ou perfura o coração mata na hora, seja qual for o dano.
KillShots={4}

[XRay]
; Registro de raio-X (F11, depois Tab): as MaxEntries pessoas mais recentes e os MaxEntries animais mais recentes ficam em enRAGE\xray_log.json.
MaxEntries={5}
; Detail: Auto (o melhor que cabe no limite de retângulos) / High / Medium / Low.
Detail={6}
; O limite por quadro do jogo para retângulos desenhados por script (ele descarta o resto sem avisar). O raio-X usa
; o que o menu deixar sobrando. Meça com a tela de calibração: K no registro de raio-X.
RectLimit={7}
; Cada letra de texto na tela parece sair do mesmo limite por quadro (o texto do relatório do raio-X deixava o esqueleto
; desenhado pela metade). O orçamento do raio-X desconta essa quantidade de unidades por letra desenhada. Aumente se ainda faltarem ossos.
GlyphCost={8}
